mapper.select:
SELECT COUNT(*)
FROM ai_feedback_knowledge_relation
WHERE feedback_id = #{feedbackId}

SELECT COUNT(DISTINCT k.knowledge_key)
FROM ai_feedback_knowledge_relation r
INNER JOIN ai_knowledge k
    ON k.knowledge_key = r.knowledge_key
   AND k.status = 1
   AND k.embedding_status = 1
   AND k.embedding_model = #{embeddingModel}
   AND k.embedding_dimensions = #{embeddingDimensions}
WHERE r.feedback_id = #{feedbackId}
